(* [comment removed for export] *)
Fixpoint bytes_val (l : list Z) : Z :=
  match l with [] => 0 | b :: t => b + 256 * bytes_val t end.

Definition all_bytes (l : list Z) : Prop := forall i, 0 <= Znth i l < 256.

