Lemma split32 y : 0 <= y < 2^32 ->
  y = y mod 2^8 + 2^8 * ((y / 2^8) mod 2^8) + 2^16 * ((y / 2^16) mod 2^8) + 2^24 * (y / 2^24).
Proof.
