Lemma repeats_of_exact x m r :
  0 <= x < 2^32 -> 0 <= m <= 11 -> 0 <= r <= 2 ->
  x mod 2^(2*m+2) = (2^(2*m) - 1) + r * 2^(2*m) ->
  repeats_of x = Ok m.
